package repository

import (
	"errors"
	"reflect"
	"sync"
	"sync/atomic"
	"testing"
)

// 固定参考的 ASCII 期望；星面字符使用显式 UTF-16 码元，不由被测函数生成。
// ASCII expectations from fixed references; astral units are explicit,
// never generated by the function under test.
func loadedIdentityTestASCII(s string) []uint16 {
	u := make([]uint16, len(s))
	for i := 0; i < len(s); i++ {
		u[i] = uint16(s[i])
	}
	return u
}

func loadedIdentityTestPath(t *testing.T, repo, parent, name string, file bool) Path {
	t.Helper()
	p, err := NewPath(repo, parent, name, file)
	if err != nil {
		t.Fatalf("construct input Path: %v", err)
	}
	return p
}

func loadedIdentityTestCall(t *testing.T, p Path) [3][]uint16 {
	t.Helper()
	r, path, name, err := LoadedFileIdentity(p)
	if err != nil {
		t.Fatalf("LoadedFileIdentity: %v", err)
	}
	return [3][]uint16{r, path, name}
}

func loadedIdentityTestCheck(t *testing.T, got, want [3][]uint16) {
	t.Helper()
	for i := range want {
		if got[i] == nil || !reflect.DeepEqual(got[i], want[i]) {
			t.Errorf("field %d = %v (nil=%v), want %v (nonnull)", i, got[i], got[i] == nil, want[i])
		}
	}
}

// 精确类参考的合成路径输入：先构造 NodePath 域，再核对三个独立加载字段。
// Synthetic exact-class reference inputs: construct the NodePath domain
// first, then verify the three independent loaded fields.
func TestLoadedFileIdentityReferenceFields(t *testing.T) {
	u := loadedIdentityTestASCII
	rows := []struct {
		name, repo, parent, nodeName string
		want                         [3][]uint16
	}{
		{"ordinary", "rk", "dir", "a.bin", [3][]uint16{u("rk"), u("dir/a.bin"), u("a.bin")}},
		{"repo trim", " rk ", "", "a.bin", [3][]uint16{u("rk"), u("a.bin"), u("a.bin")}},
		{"exposed leading space", "rk", "", "/ a/", [3][]uint16{u("rk"), u(" a"), u(" a")}},
		{"exposed trailing space", "rk", "", "/a /", [3][]uint16{u("rk"), u("a "), u("a ")}},
		{"boundary slashes", "rk", "", "/a/", [3][]uint16{u("rk"), u("a"), u("a")}},
		{"properties name", "rk", "", "f:properties", [3][]uint16{u("rk"), u("f:properties"), u("f")}},
		{"single metadata strip", "rk", "", "f:properties:statistics", [3][]uint16{u("rk"), u("f:properties:statistics"), u("f:properties")}},
		{"plain maven name", "rk", "", "maven-metadata.xml", [3][]uint16{u("rk"), u("maven-metadata.xml"), u("maven-metadata.xml")}},
		{"prefixed maven name", "rk", "", "x:maven-metadata.xml", [3][]uint16{u("rk"), u("x:maven-metadata.xml"), u("x")}},
		{"backslash preserved in path", "rk", "a\\b", "c\\d", [3][]uint16{u("rk"), u("a\\b/c\\d"), u("d")}},
		{"java blank parent", "rk", "\u2003", "f", [3][]uint16{u("rk"), u("f"), u("f")}},
		{"file root nonnull empties", "rk", "", "", [3][]uint16{u("rk"), {}, {}}},
		{"slash name with parent", "rk", "d", "/", [3][]uint16{u("rk"), u("d"), u("d")}},
		{"internal duplicate slashes", "rk", "//a//", "b//c", [3][]uint16{u("rk"), u("a/b//c"), u("c")}},
		{"astral name", "rk", "", "x\U0001F600", [3][]uint16{u("rk"), {'x', 0xd83d, 0xde00}, {'x', 0xd83d, 0xde00}}},
		{"statistics with parent", "rk", "d", "x:statistics", [3][]uint16{u("rk"), u("d/x:statistics"), u("x")}},
		{"repo boundary nul trims", "\x00rk\x00", "", "f", [3][]uint16{u("rk"), u("f"), u("f")}},
		{"repo interior nul preserved", "r\x00k", "", "f", [3][]uint16{u("r\x00k"), u("f"), u("f")}},
	}
	for _, row := range rows {
		t.Run(row.name, func(t *testing.T) {
			p := loadedIdentityTestPath(t, row.repo, row.parent, row.nodeName, true)
			before := p
			loadedIdentityTestCheck(t, loadedIdentityTestCall(t, p), row.want)
			if p != before {
				t.Error("input Path changed")
			}
		})
	}
}

// 原始 parent='/'、空名在 NewPath 归一化之前拒绝，不能算 helper 的拒绝。
// Raw parent='/' with an empty name rejects before NewPath normalization;
// it is not a rejection after the identity helper received a valid Path.
func TestLoadedFileIdentityNodePathConstructionRejectsFirst(t *testing.T) {
	p, err := NewPath("rk", "/", "", true)
	if !errors.Is(err, ErrInvalidPath) || p != (Path{}) {
		t.Fatalf("NewPath = (%+v, %v), want zero Path and ErrInvalidPath", p, err)
	}
}

// 结构/UTF-8 为本地入口政策；trim 空 repo 与内部 NUL 有单独目标类参考。
// Structural/UTF-8 guards are local policy; trim-empty repo and interior
// NUL rejections also have separate target-class references.
func TestLoadedFileIdentityRejectsInputsWithoutPartialOutput(t *testing.T) {
	rows := []struct {
		name string
		path Path
	}{
		{"zero Path", Path{}},
		{"folder", loadedIdentityTestPath(t, "rk", "d", "f", false)},
		{"invalid utf8 repo", loadedIdentityTestPath(t, "r\xffk", "", "f", true)},
		{"invalid utf8 parent", loadedIdentityTestPath(t, "rk", "a\xffb", "f", true)},
		{"invalid utf8 name", loadedIdentityTestPath(t, "rk", "", "f\xff", true)},
		{"repo empty after Java trim", loadedIdentityTestPath(t, "\x00", "", "a", true)},
		{"parent interior nul", loadedIdentityTestPath(t, "rk", "a\x00b", "f", true)},
		{"getter name interior nul", loadedIdentityTestPath(t, "rk", "", "x\x00y", true)},
	}
	for _, row := range rows {
		t.Run(row.name, func(t *testing.T) {
			r, path, name, err := LoadedFileIdentity(row.path)
			if !errors.Is(err, ErrInvalidPath) {
				t.Fatalf("error = %v, want ErrInvalidPath", err)
			}
			if err.Error() != "repository: invalid node path" {
				t.Errorf("error text = %q, want fixed input-free error", err.Error())
			}
			if r != nil || path != nil || name != nil {
				t.Errorf("partial output = %v/%v/%v, want three nils", r, path, name)
			}
		})
	}
}

// 三个字段刻意同值；修改一份不能影响另外两份或另一调用的结果。
// All fields deliberately have the same value: mutating one must affect
// neither the other fields nor the result of another call.
func TestLoadedFileIdentityOutputsAreIndependent(t *testing.T) {
	p := loadedIdentityTestPath(t, "same", "", "same", true)
	want := [3][]uint16{{'s', 'a', 'm', 'e'}, {'s', 'a', 'm', 'e'}, {'s', 'a', 'm', 'e'}}
	for selected := range want {
		first := loadedIdentityTestCall(t, p)
		second := loadedIdentityTestCall(t, p)
		loadedIdentityTestCheck(t, first, want)
		loadedIdentityTestCheck(t, second, want)
		// 长度异常已由断言报告，禁止用越界 panic 充当行为失败。
		// Report a bad length by assertion, never by an indexing panic.
		if len(first[selected]) == 0 {
			t.Fatal("expected a nonempty mutable output")
		}
		first[selected][0] = 0xffff
		for field := range want {
			if field != selected && !reflect.DeepEqual(first[field], want[field]) {
				t.Errorf("mutating field %d changed sibling %d", selected, field)
			}
		}
		loadedIdentityTestCheck(t, second, want)
		loadedIdentityTestCheck(t, loadedIdentityTestCall(t, p), want)
		if p.Repo() != "same" || p.Parent() != "" || p.Name() != "same" || !p.IsFile() {
			t.Error("mutating an output changed the input Path")
		}
	}
}

// 共享只读 Path，每次只写自己的返回切片；不要求任何地址或内部存储布局。
// Share a read-only Path and mutate only each call's returned slices;
// require no address or internal-layout properties.
func TestLoadedFileIdentityConcurrentReaders(t *testing.T) {
	p := loadedIdentityTestPath(t, " rk ", "d", "x\U0001F600:properties", true)
	want := [3][]uint16{
		{'r', 'k'},
		{'d', '/', 'x', 0xd83d, 0xde00, ':', 'p', 'r', 'o', 'p', 'e', 'r', 't', 'i', 'e', 's'},
		{'x', 0xd83d, 0xde00},
	}
	var failed int32
	var wg sync.WaitGroup
	for worker := 0; worker < 8; worker++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for iteration := 0; iteration < 16; iteration++ {
				r, path, name, err := LoadedFileIdentity(p)
				got := [3][]uint16{r, path, name}
				if err != nil {
					atomic.AddInt32(&failed, 1)
					continue
				}
				for field := range want {
					if got[field] == nil || !reflect.DeepEqual(got[field], want[field]) {
						atomic.AddInt32(&failed, 1)
					}
					for i := range got[field] {
						got[field][i] = 0xffff
					}
				}
			}
		}()
	}
	wg.Wait()
	if n := atomic.LoadInt32(&failed); n != 0 {
		t.Errorf("concurrent calls had %d field/error failures", n)
	}
	loadedIdentityTestCheck(t, loadedIdentityTestCall(t, p), want)
	if p.Repo() != " rk " || p.Parent() != "d" || p.Name() != "x\U0001F600:properties" || !p.IsFile() {
		t.Error("concurrent calls changed the input Path")
	}
}
